const vars = [
  "eState","rSpeed","rSpeedRequest","rPosition",
  "bStartCmd","bStopCmd","bResetCmd","bFaultInject",
  "bWearInject","bJamInject","bSlipInject","bOverloadInject",
  "nStartCount","nStopCount","nResetCount","nFaultCount",
  "nPlcTime","eFaultCode","bMaintenanceCmd","nMaintenanceCount",
  "rMotorCurrent","rMotorTemp","rBearingTemp","rVibration","rAmbientTemp"
];
flow.set("vars", vars);
   return [vars.map(v => ({ topic: "ns=4;s=MAIN." + v }))];

const t = String(msg.topic || "");
const i = t.indexOf("MAIN.");
if (i < 0) { node.status({fill:"red",shape:"ring",text:"no MAIN in: " + t}); return null; }
const name = t.slice(i + 5);
if (msg.payload === null || msg.payload === undefined) { node.status({fill:"yellow",shape:"ring",text:"null " + name}); return null; }
const c = flow.get("cache") || {};
const changed = (name === "nPlcTime" && c.nPlcTime !== msg.payload);
c[name] = msg.payload;
flow.set("cache", c);
if (changed) flow.set("lastUpdate", Date.now());
node.status({fill:"green",shape:"dot",text:name});
return null;

const vars = flow.get("vars") || [];
const cache = flow.get("cache") || {};
const last = flow.get("lastUpdate") || 0;

const missing = vars.filter(v => !(v in cache));
if (missing.length) { node.status({fill:"yellow",shape:"ring",text:"missing: " + missing.join(",")}); return null; }
if (Date.now() - last > 2000) { node.status({fill:"red",shape:"ring",text:"stale"}); return null; }

const data = { ts: Date.now() };
for (const v of vars) data[v] = cache[v];
data.readTs = last;
node.status({fill:"green",shape:"dot",text:"publishing"});
return { topic: "conveyor2/telemetry", payload: JSON.stringify(data) };

// Node-RED function node: "csv row"  (replaces the old one)
// Adds phase + label from the scenario runner. These are TARGETS, never features.
const d = JSON.parse(msg.payload);
const prev = flow.get("lastPlcTime");
if (d.nPlcTime === prev) return null;        // drop duplicate samples
flow.set("lastPlcTime", d.nPlcTime);

const runId = flow.get("runId") || "unset";
if (runId === "idle" || runId === "unset") return null;   // don't log outside runs
const phase = flow.get("phase") || "idle";
const label = flow.get("label") || "none";
const cols = ["ts","nPlcTime","eState","eFaultCode","rSpeed","rSpeedRequest","rPosition",
              "rMotorCurrent","rMotorTemp","rBearingTemp","rVibration","rAmbientTemp",
              "nStartCount","nStopCount","nResetCount","nFaultCount","nMaintenanceCount"];

const row = runId + "," + cols.map(c => d[c]).join(",") + "," + phase + "," + label + "\n";

if (!flow.get("headerWritten:" + runId)) {
    flow.set("headerWritten:" + runId, true);
    msg.payload = "run_id," + cols.join(",") + ",phase,label\n" + row;
} else {
    msg.payload = row;
}
msg.filename = "C:\\Users\\varun\\Documents\\TcXaeShell\\BeltTwin\\data\\" + runId + ".csv";
return msg;

const id = "run_" + new Date().toISOString().replace(/[:.]/g,"-");
flow.set("runId", id);
flow.set("headerWritten:" + id, false);
flow.set("lastPlcTime", null);
node.status({fill:"blue",shape:"dot",text:id});
return null;

// Node-RED function node: "cmd to opcua"
// Accepts: "start", {"cmd":"start"}, "speed 60", {"cmd":"speed","value":60}
const map = {
    start:       "bStartCmd",
    stop:        "bStopCmd",
    reset:       "bResetCmd",
    fault:       "bFaultInject",
    jam:         "bJamInject",
    slip:        "bSlipInject",
    overload:    "bOverloadInject",
    wear:        "bWearInject",
    maintenance: "bMaintenanceCmd"
};

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) {
        const parts = p.trim().split(/\s+/);
        p = { cmd: parts[0], value: parts[1] };
    }
}

const cmd = p && String(p.cmd).toLowerCase();

// speed setpoint: the only non-boolean write, range-checked
if (cmd === "speed") {
    const s = Number(p.value);
    if (!Number.isFinite(s) || s < 0 || s > 80) {
        node.warn("rejected speed: " + JSON.stringify(p));
        return null;
    }
    node.status({fill:"blue",shape:"dot",text:"speed " + s});
    return { topic: "ns=4;s=MAIN.rSpeedRequest;datatype=Float", payload: s };
}

const v = map[cmd];
if (!v) { node.warn("rejected command: " + JSON.stringify(p)); return null; }

node.status({fill:"blue",shape:"dot",text:cmd});
return { topic: "ns=4;s=MAIN." + v + ";datatype=Boolean", payload: true };

// Node-RED function node: "scenario runner"  (Setup tab: Outputs = 2)
// Inputs:  "tick" every 0.5 s, "go" to start a campaign, "abort" to stop it.
// Output 1 -> "cmd to opcua" (plain-string commands, same whitelist as MQTT)
// Output 2 -> write file node, data\manifest.csv (append, no added newline)

// ---- dry run: set to null for the full campaign ----
const TEST_PLAN = null;

// ---- campaign definition ----
const SPEEDS = [40, 50, 60, 70, 80];
const FAULTS = ["jam", "slip", "overload", "wear"];
const REPS_PER_SPEED    = 4;   // x5 speeds = 20 runs per fault
const HEALTHY_PER_SPEED = 2;   // x2 kinds x5 speeds = 20 healthy runs

const FAULT_CODE = { jam: 1, slip: 2, wear: 3, overload: 4 };
const TIMEOUT_S  = { jam: 15, slip: 90, overload: 150, wear: 900 };  // ~2x measured trip time
const HOLD_MIN_S = 20, HOLD_MAX_S = 60;       // healthy interval before injection
const HEALTHY_S = 180, CHANGE_AT_S = 90;      // healthy runs
const SETTLE_TOL = 0.15, SETTLE_TICKS = 10;   // 10-s mean within 0.15 degC, held for 10 ticks (5 s)
const SETTLE_WIN = 20;                        // ticks in the rolling mean (20 x 0.5 s = 10 s)
const WARMUP_TIMEOUT_S = 1200;
const POST_TRIP_S = 10;
const STALE_MS = 3000;

// ---- state ----
let S = context.get("S") || { mode: "idle" };
const c = flow.get("cache") || {};
const now = Date.now();
const fresh = now - (flow.get("lastUpdate") || 0) < STALE_MS;
const cmds = [];
let manifest = null;

const send = s => cmds.push({ payload: s });
const setLabel = (phase, label) => { flow.set("phase", phase); flow.set("label", label); };
const secs = () => (now - S.t0) / 1000;
const go = step => { S.step = step; S.t0 = now; };

function shuffle(a) {
    for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}

function buildPlan() {
    if (TEST_PLAN) return TEST_PLAN.map(r => Object.assign({}, r));
    const p = [];
    for (const sp of SPEEDS) {
        for (const f of FAULTS)
            for (let k = 0; k < REPS_PER_SPEED; k++) p.push({ kind: f, speed: sp });
        for (let k = 0; k < HEALTHY_PER_SPEED; k++) {
            p.push({ kind: "healthy", speed: sp });
            const others = SPEEDS.filter(x => x !== sp);
            p.push({ kind: "healthy_change", speed: sp,
                     speed2: others[Math.floor(Math.random() * others.length)] });
        }
    }
    return shuffle(p);
}

function finish(status) {
    const r = S.run || {};
    const f = v => (v === undefined || v === null) ? "" : v;
    manifest = { payload: [f(r.id), f(r.kind), f(r.speed), f(r.speed2), f(r.hold),
                           f(r.injectTs), f(r.tripTs), f(r.tripCode), f(FAULT_CODE[r.kind]),
                           status, f(r.staleTicks), f(r.warmup_s)].join(",") + "\n" };
    S.idx++;
    S.run = null;
    go("prep");
}

// ---- control messages ----
if (msg.payload === "go") {
    if (S.mode === "running") { node.warn("runner already running"); return null; }
    S = { mode: "running", plan: buildPlan(), idx: 0, run: null };
    go("prep");
    context.set("S", S);
    node.status({ fill: "blue", shape: "dot", text: "starting, " + S.plan.length + " runs" });
    return [null, { payload: "run_id,kind,speed,speed2,hold_s,inject_ts,trip_ts,trip_code,expected_code,status,stale_ticks,warmup_s\n" }];
}

if (msg.payload === "abort") {
    if (S.mode === "running") {
        send("stop");
        if (S.run) finish("aborted");
    }
    S.mode = "idle";
    flow.set("runId", "idle");
    setLabel("idle", "none");
    context.set("S", S);
    node.status({ fill: "grey", shape: "ring", text: "aborted" });
    return [cmds.length ? cmds : null, manifest];
}

// ---- tick ----
if (S.mode !== "running") return null;

if (!fresh) {
    if (S.run) S.run.staleTicks++;
    node.status({ fill: "red", shape: "ring", text: "stale data - paused" });
    context.set("S", S);
    return null;
}

if (S.idx >= S.plan.length) {
    S.mode = "idle";
    flow.set("runId", "idle");
    setLabel("idle", "none");
    context.set("S", S);
    node.status({ fill: "green", shape: "dot", text: "campaign done: " + S.plan.length + " runs" });
    return null;
}

const planned = S.plan[S.idx];
const st = c.eState;
const amb = (typeof c.rAmbientTemp === "number") ? c.rAmbientTemp : 22;

switch (S.step) {

case "prep":
    setLabel("reset", "none");
    if (st === 3) { if (secs() > 1) { send("reset"); S.t0 = now; } break; }
    if (st === 1 || st === 2) { if (secs() > 1) { send("stop"); S.t0 = now; } break; }
    if (st !== 0) break;
    S.run = Object.assign({}, planned, {
        id: "run_" + new Date(now).toISOString().replace(/[:.]/g, "-") + "_" + planned.kind + "_" + planned.speed,
        staleTicks: 0
    });
    flow.set("runId", S.run.id);
    flow.set("headerWritten:" + S.run.id, false);
    flow.set("lastPlcTime", null);
    setLabel("warmup", "none");
    send("speed " + S.run.speed);
    send("maintenance");
    S.tries = 0;
    go("arm");
    break;

case "arm":
    setLabel("warmup", "none");
    if (secs() < 1) break;
    if (Math.abs(c.rSpeedRequest - S.run.speed) > 0.01) {
        if (++S.tries > 3) { finish("speed_write_failed"); break; }
        send("speed " + S.run.speed);
        S.t0 = now;
        break;
    }
    send("start");
    S.lastStart = now;
    S.settle = 0;
    S.mBuf = [];
    S.bBuf = [];
    go("warmup");
    break;

case "warmup": {
    setLabel("warmup", "none");
    if (secs() > WARMUP_TIMEOUT_S) { send("stop"); finish("warmup_timeout"); break; }
    if (st === 3) { finish("unexpected_fault_in_warmup"); break; }
    if (st === 0 && now - S.lastStart > 3000) { send("start"); S.lastStart = now; break; }
    if (st !== 2) break;
    const mT = amb + 0.5 * S.run.speed;
    const bT = amb + 0.175 * S.run.speed;
    S.mBuf = S.mBuf.concat(c.rMotorTemp).slice(-SETTLE_WIN);
    S.bBuf = S.bBuf.concat(c.rBearingTemp).slice(-SETTLE_WIN);
    const avg = a => a.reduce((x, y) => x + y, 0) / a.length;
    const ok = S.mBuf.length === SETTLE_WIN
            && Math.abs(avg(S.mBuf) - mT) < SETTLE_TOL
            && Math.abs(avg(S.bBuf) - bT) < SETTLE_TOL;
    S.settle = ok ? S.settle + 1 : 0;
    if (S.settle >= SETTLE_TICKS) {
        S.run.warmup_s = Math.round(secs());
        S.run.hold = S.run.kind.startsWith("healthy")
            ? HEALTHY_S
            : Math.round(HOLD_MIN_S + Math.random() * (HOLD_MAX_S - HOLD_MIN_S));
        setLabel("healthy", "none");
        go("healthy");
    }
    break;
}

case "healthy":
    setLabel("healthy", "none");
    if (st !== 2) { finish("unexpected_state_" + st + "_in_healthy"); break; }
    if (S.run.kind === "healthy_change" && !S.run.changed && secs() >= CHANGE_AT_S) {
        send("speed " + S.run.speed2);
        S.run.changed = true;
    }
    if (secs() >= S.run.hold) {
        if (S.run.kind.startsWith("healthy")) {
            send("stop");
            finish("ok");
        } else {
            send(S.run.kind);
            S.run.injectTs = now;
            setLabel("developing", S.run.kind);
            go("developing");
        }
    }
    break;

case "developing":
    setLabel("developing", S.run.kind);
    if (st === 3) {
        S.run.tripTs = now;
        S.run.tripCode = c.eFaultCode;
        setLabel("faulted", S.run.kind);
        go("faulted");
        break;
    }
    if (st !== 2) { finish("unexpected_state_" + st + "_in_developing"); break; }
    if (secs() > TIMEOUT_S[S.run.kind]) { send("stop"); finish("no_trip_timeout"); }
    break;

case "faulted":
    setLabel("faulted", S.run.kind);
    if (secs() >= POST_TRIP_S) {
        send("reset");
        send("maintenance");
        finish(S.run.tripCode === FAULT_CODE[S.run.kind] ? "ok" : "wrong_code");
    }
    break;
}

node.status({ fill: "blue", shape: "dot",
    text: (S.idx + 1) + "/" + S.plan.length + " " + planned.kind + "@" + planned.speed +
          " " + S.step + " " + Math.round(secs()) + "s" });
context.set("S", S);
return [cmds.length ? cmds : null, manifest];
